scwin.trigger1_onclick = function(e) {
    scwin.tempMenu();
};
scwin.dataList1_onaftercolumnfilterchange = function() {
    //debugger;
    console.log("onaftercolumnfilterchange");
    localStorage.setItem('log', 'onaftercolumnfilterchange');
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd_rptList_column11_filter').click()");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd_rptList_customFilter_list').children[1].click()");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("set", "localStorage.setItem('log', '')");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd_rptList_customFilter_list').children[1].click()");
    WebSquare.wUnit.addCommand("pause", "300");
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log') == 'onaftercolumnfilterchange'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload = function() {
    if (typeof scwin.onpageload === "function") {
        //scwin.onpageload();
    }
    localStorage.removeItem("log");
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
